   333	int Interpreter::Hex2Bin(const char *aHex, uint8_t *aBin, uint16_t aBinLength)
   334	{
   335	    size_t      hexLength = strlen(aHex);
   336	    const char *hexEnd    = aHex + hexLength;
   337	    uint8_t *   cur       = aBin;
   338	    uint8_t     numChars  = hexLength & 1;
   339	    uint8_t     byte      = 0;
   340	    int         rval;
   341	
   342	    VerifyOrExit((hexLength + 1) / 2 <= aBinLength, rval = -1);
   343	
   344	    while (aHex < hexEnd)
   345	    {
   346	        if ('A' <= *aHex && *aHex <= 'F')
   347	        {
   348	            byte |= 10 + (*aHex - 'A');
   349	        }
   350	        else if ('a' <= *aHex && *aHex <= 'f')
   351	        {
   352	            byte |= 10 + (*aHex - 'a');
   353	        }
   354	        else if ('0' <= *aHex && *aHex <= '9')
   355	        {
   356	            byte |= *aHex - '0';
   357	        }
   358	        else
   359	        {
   360	            ExitNow(rval = -1);
   361	        }
   362	
   363	        aHex++;
   364	        numChars++;
   365	
   366	        if (numChars >= 2)
   367	        {
   368	            numChars = 0;
   369	            *cur++   = byte;
   370	            byte     = 0;
   371	        }
   372	        else
   373	        {
   374	            byte <<= 4;
   375	        }
   376	    }
   377	
   378	    rval = static_cast<int>(cur - aBin);
   379	
   380	exit:
   381	    return rval;
   382	}
